CREATE TABLE `Exercise` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `category` TEXT NOT NULL, `isMainLift` INTEGER NOT NULL);
CREATE TABLE `UserMax` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `exerciseId` INTEGER NOT NULL, `oneRepMax` REAL NOT NULL, `trainingMaxPct` REAL NOT NULL, `updatedDate` TEXT NOT NULL, FOREIGN KEY(`exerciseId`) REFERENCES `Exercise`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE UNIQUE INDEX `index_UserMax_exerciseId` ON `UserMax` (`exerciseId`);
CREATE TABLE `Program` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `description` TEXT NOT NULL, `periodizationType` TEXT NOT NULL, `cycleWeeks` INTEGER NOT NULL, `daysPerWeek` INTEGER NOT NULL, `progressionRule` TEXT NOT NULL, `isBuiltIn` INTEGER NOT NULL);
CREATE TABLE `ProgramDay` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `programId` INTEGER NOT NULL, `weekIndex` INTEGER NOT NULL, `dayIndex` INTEGER NOT NULL, `name` TEXT NOT NULL, FOREIGN KEY(`programId`) REFERENCES `Program`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `PlannedSet` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `programDayId` INTEGER NOT NULL, `exerciseId` INTEGER NOT NULL, `setNumber` INTEGER NOT NULL, `reps` INTEGER NOT NULL, `weightFormula` TEXT NOT NULL, `isAmrap` INTEGER NOT NULL, repsText TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', FOREIGN KEY(`programDayId`) REFERENCES `ProgramDay`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`exerciseId`) REFERENCES `Exercise`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `WorkoutLog` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `date` TEXT NOT NULL, `programDayId` INTEGER, cycle INTEGER NOT NULL DEFAULT 1, completed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE `ActualSet` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `workoutLogId` INTEGER NOT NULL, `exerciseId` INTEGER NOT NULL, `setNumber` INTEGER NOT NULL, `reps` INTEGER, `weight` REAL, `notes` TEXT NOT NULL, FOREIGN KEY(`workoutLogId`) REFERENCES `WorkoutLog`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`exerciseId`) REFERENCES `Exercise`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `UserProgramState` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `programId` INTEGER NOT NULL, `currentWeek` INTEGER NOT NULL, `currentDay` INTEGER NOT NULL, `cycleCount` INTEGER NOT NULL, FOREIGN KEY(`programId`) REFERENCES `Program`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE UNIQUE INDEX `index_UserProgramState_programId` ON `UserProgramState` (`programId`);
